141	<main>
142	  <h1>Meeting Cost Timer</h1>
143	  <p class="sub">Watch the money burn, one second at a time.</p>
144	
145	  <div class="inputs">
146	    <label for="people">People in the meeting
147	      <input id="people" type="number" min="1" step="1" inputmode="numeric" placeholder="e.g. 6">
148	    </label>
149	    <label for="rate">Average hourly pay (USD)
150	      <span class="field"><span class="prefix">$</span><input id="rate" type="number" min="0" step="any" inputmode="decimal" placeholder="e.g. 90"></span>
151	    </label>
152	  </div>
153	  <p class="hint" id="hint" aria-live="polite"></p>
154	
155	  <div class="display">
156	    <div class="cost" id="cost" aria-live="off">$0.00</div>
157	    <div class="elapsed" id="elapsed">00:00:00</div>
158	  </div>
159	
160	  <div class="buttons">
161	    <button id="start" type="button" disabled>Start</button>
162	    <button id="reset" type="button" class="secondary">Reset</button>
163	  </div>
164	
165	  <div class="toast" id="toast" role="status" aria-live="polite" hidden></div>
166	</main>
167	
168	<script id="cost-logic">
169	  // Pure logic: no DOM access. Tested by tests/cost-logic.test.mjs.
170	  var MILESTONES = [
171	    { threshold: 100, message: "That's a lot of fancy coffee ☕" },
172	    { threshold: 500, message: "We could've catered this 🍕" },
173	    { threshold: 1000, message: "This meeting now costs more than a laptop 💻" }
174	  ];
175	
176	  function computeCost(people, rate, elapsedMs) {
177	    return (people * rate * (elapsedMs / 1000)) / 3600;
178	  }
179	
180	  // Highest milestone threshold crossed going from prevCost to cost, or null.
181	  function milestoneFor(prevCost, cost) {
182	    var hit = null;
183	    for (var i = 0; i < MILESTONES.length; i++) {
184	      var m = MILESTONES[i];
185	      if (prevCost < m.threshold && cost >= m.threshold) hit = m;
186	    }
187	    return hit;
188	  }
189	
190	  function parseNumber(raw) {
191	    if (raw === null || raw === undefined) return NaN;
192	    var s = String(raw).trim();
193	    if (s === "") return NaN;
194	    return Number(s);
195	  }
196	
197	  // Returns { valid, people, rate, hint }.
198	  function validateInputs(peopleRaw, rateRaw) {
199	    var people = parseNumber(peopleRaw);
200	    var rate = parseNumber(rateRaw);
201	    var hint = "";
202	    if (!Number.isFinite(people) || !Number.isInteger(people) || people < 1) {
203	      hint = "Enter a whole number of people (1 or more).";
204	    } else if (!Number.isFinite(rate) || rate <= 0) {
205	      hint = "Enter an hourly pay above $0.";
206	    }
207	    return { valid: hint === "", people: people, rate: rate, hint: hint };
208	  }
209	
210	  function formatCost(cost) {
211	    return "$" + cost.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
212	  }
213	
214	  function formatElapsed(elapsedMs) {
215	    var total = Math.floor(elapsedMs / 1000);
216	    var h = Math.floor(total / 3600);
217	    var m = Math.floor((total % 3600) / 60);
218	    var s = total % 60;
219	    function pad(n) { return (n < 10 ? "0" : "") + n; }
220	    return pad(h) + ":" + pad(m) + ":" + pad(s);
221	  }
222	</script>
223	
224	<script>
225	  (function () {
226	    var peopleEl = document.getElementById("people");
227	    var rateEl = document.getElementById("rate");
228	    var hintEl = document.getElementById("hint");
229	    var costEl = document.getElementById("cost");
230	    var elapsedEl = document.getElementById("elapsed");
231	    var startBtn = document.getElementById("start");
232	    var resetBtn = document.getElementById("reset");
233	    var toastEl = document.getElementById("toast");
234	
235	    // state: "idle" | "running" | "paused"
236	    var state = "idle";
237	    var people = 0, rate = 0;
238	    var accumulatedMs = 0;   // elapsed time banked before the current run segment
239	    var segmentStart = 0;    // Date.now() when the current run segment started
240	    var lastCost = 0;        // cost at the previous render, for milestone crossing
241	    var timerId = null;
242	
243	    function elapsedNow() {
244	      return state === "running" ? accumulatedMs + (Date.now() - segmentStart) : accumulatedMs;
245	    }
246	
247	    function showMilestone(m) {
248	      toastEl.textContent = m.message;
249	      toastEl.hidden = false;
250	      toastEl.classList.remove("pop");
251	      void toastEl.offsetWidth; // restart animation
252	      toastEl.classList.add("pop");
253	    }
254	
255	    function render() {
256	      var ms = elapsedNow();
257	      var cost = computeCost(people, rate, ms);
258	      var m = milestoneFor(lastCost, cost);
259	      if (m) showMilestone(m);
260	      lastCost = cost;
261	      costEl.textContent = formatCost(cost);
262	      elapsedEl.textContent = formatElapsed(ms);
263	    }
264	
265	    function refreshValidation() {
266	      if (state !== "idle") return;
267	      var v = validateInputs(peopleEl.value, rateEl.value);
268	      var untouched = peopleEl.value === "" && rateEl.value === "";
269	      startBtn.disabled = !v.valid;
270	      hintEl.textContent = v.valid || untouched ? (untouched ? "Enter people and hourly pay to start." : "") : v.hint;
271	    }
272	
273	    function setInputsLocked(locked) {
274	      peopleEl.disabled = locked;
275	      rateEl.disabled = locked;
276	    }
277	
278	    function start() {
279	      if (state === "idle") {
280	        var v = validateInputs(peopleEl.value, rateEl.value);
281	        if (!v.valid) { refreshValidation(); return; }
282	        people = v.people;
283	        rate = v.rate;
284	        setInputsLocked(true);
285	        hintEl.textContent = "";
286	      }
287	      state = "running";
288	      segmentStart = Date.now();
289	      startBtn.textContent = "Pause";
290	      timerId = setInterval(render, 250);
291	      render();
292	    }
293	
294	    function pause() {
295	      accumulatedMs += Date.now() - segmentStart;
296	      state = "paused";
297	      clearInterval(timerId);
298	      timerId = null;
299	      startBtn.textContent = "Resume";
300	      render();
301	    }
302	
303	    function reset() {
304	      clearInterval(timerId);
305	      timerId = null;
306	      state = "idle";
307	      accumulatedMs = 0;
308	      lastCost = 0;
309	      people = 0;
310	      rate = 0;
311	      costEl.textContent = formatCost(0);
312	      elapsedEl.textContent = formatElapsed(0);
313	      toastEl.hidden = true;
314	      toastEl.textContent = "";
315	      toastEl.classList.remove("pop");
316	      startBtn.textContent = "Start";
317	      setInputsLocked(false);
318	      refreshValidation();
319	    }
320	
321	    startBtn.addEventListener("click", function () {
322	      if (state === "running") pause(); else start();
323	    });
324	    resetBtn.addEventListener("click", reset);
325	    peopleEl.addEventListener("input", refreshValidation);
326	    rateEl.addEventListener("input", refreshValidation);
327	    // Catch up immediately when a hidden tab becomes visible again.
328	    document.addEventListener("visibilitychange", function () {
329	      if (!document.hidden && state === "running") render();
330	    });
331	
332	    reset();
333	  })();
334	</script>
335	</body>
336	</html>
