+    }
+
+    function setInputsLocked(locked) {
+      peopleEl.disabled = locked;
+      rateEl.disabled = locked;
+    }
+
+    function start() {
+      if (state === "idle") {
+        var v = validateInputs(peopleEl.value, rateEl.value);
+        if (!v.valid) { refreshValidation(); return; }
+        people = v.people;
+        rate = v.rate;
+        setInputsLocked(true);
+        hintEl.textContent = "";
+      }
+      state = "running";
+      segmentStart = Date.now();
+      startBtn.textContent = "Pause";
+      timerId = setInterval(render, 250);
+      render();
+    }
+
+    function pause() {
+      accumulatedMs += Date.now() - segmentStart;
+      state = "paused";
+      clearInterval(timerId);
+      timerId = null;
+      startBtn.textContent = "Resume";
+      render();
+    }
+
+    function reset() {
+      clearInterval(timerId);
+      timerId = null;
+      state = "idle";
+      accumulatedMs = 0;
+      lastCost = 0;
+      people = 0;
+      rate = 0;
