    };
  }

  function parseNumber(raw) {
    if (raw === null || raw === undefined) return NaN;
    var s = String(raw).trim();
    if (s === "") return NaN;
    return Number(s);
  }

  // Returns { valid, people, rate, hint }.
  function validateInputs(peopleRaw, rateRaw) {
    var people = parseNumber(peopleRaw);
    var rate = parseNumber(rateRaw);
    var hint = "";
    if (!Number.isFinite(people) || !Number.isInteger(people) || people < 1) {
      hint = "Enter a whole number of people (1 or more).";
    } else if (!Number.isFinite(rate) || rate <= 0) {
      hint = "Enter an hourly pay above $0.";
    }
    return { valid: hint === "", people: people, rate: rate, hint: hint };
  }

  function formatCost(cost) {
    return "$" + cost.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }

  function formatElapsed(elapsedMs) {
    var total = Math.floor(elapsedMs / 1000);
    var h = Math.floor(total / 3600);
    var m = Math.floor((total % 3600) / 60);
    var s = total % 60;
    function pad(n) { return (n < 10 ? "0" : "") + n; }
    return pad(h) + ":" + pad(m) + ":" + pad(s);
  }
</script>

<script>
  (function () {
    var peopleEl = document.getElementById("people");
    var rateEl = document.getElementById("rate");
    var hintEl = document.getElementById("hint");
    var costEl = document.getElementById("cost");
    var elapsedEl = document.getElementById("elapsed");
    var startBtn = document.getElementById("start");
    var resetBtn = document.getElementById("reset");
    var toastEl = document.getElementById("toast");

    // state: "idle" | "running" | "paused"
    var state = "idle";
    var people = 0, rate = 0;
    var stopwatch = createStopwatch(Date.now);
    var lastCost = 0;        // displayed (cent-rounded) cost at the previous render
    var timerId = null;

    function showMilestone(m) {
      toastEl.textContent = m.message;
      toastEl.hidden = false;
      toastEl.classList.remove("pop");
      void toastEl.offsetWidth; // restart animation
      toastEl.classList.add("pop");
    }

    function render() {
      var ms = stopwatch.elapsed();
      var cost = roundToCents(computeCost(people, rate, ms));
      var m = milestoneFor(lastCost, cost);
      if (m) showMilestone(m);
      lastCost = cost;
      costEl.textContent = formatCost(cost);
      elapsedEl.textContent = formatElapsed(ms);
    }

    function refreshValidation() {
      if (state !== "idle") return;
      var v = validateInputs(peopleEl.value, rateEl.value);
      var untouched = peopleEl.value === "" && rateEl.value === "";
      startBtn.disabled = !v.valid;
      hintEl.textContent = v.valid || untouched ? (untouched ? "Enter people and hourly pay to start." : "") : v.hint;
    }

    function setInputsLocked(locked) {
      peopleEl.disabled = locked;
      rateEl.disabled = locked;
    }

    function start() {
      if (state === "idle") {
        var v = validateInputs(peopleEl.value, rateEl.value);
        if (!v.valid) { refreshValidation(); return; }
        people = v.people;
        rate = v.rate;
        setInputsLocked(true);
        hintEl.textContent = "";
      }
      state = "running";
      stopwatch.start();
      startBtn.textContent = "Pause";
      timerId = setInterval(render, 250);
      render();
    }

    function pause() {
      stopwatch.pause();
      state = "paused";
      clearInterval(timerId);
      timerId = null;
      startBtn.textContent = "Resume";
      render();
    }

    function reset() {
      clearInterval(timerId);
      timerId = null;
      state = "idle";
      stopwatch.reset();
      lastCost = 0;
      people = 0;
      rate = 0;
      costEl.textContent = formatCost(0);
      elapsedEl.textContent = formatElapsed(0);
      toastEl.hidden = true;
      toastEl.textContent = "";
      toastEl.classList.remove("pop");
      startBtn.textContent = "Start";
      setInputsLocked(false);
      refreshValidation();
    }

    startBtn.addEventListener("click", function () {
      if (state === "running") pause(); else start();
    });
    resetBtn.addEventListener("click", reset);
    peopleEl.addEventListener("input", refreshValidation);
    rateEl.addEventListener("input", refreshValidation);
    // Catch up immediately when a hidden tab becomes visible again.
    document.addEventListener("visibilitychange", function () {
      if (!document.hidden && state === "running") render();
    });

    reset();
  })();
</script>

