import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import vm from "node:vm";

const html = readFileSync(new URL("../index.html", import.meta.url), "utf8");
const match = html.match(/<script id="cost-logic">([\s\S]*?)<\/script>/);
assert.ok(match, "index.html must contain <script id=\"cost-logic\">");

const ctx = vm.createContext({});
vm.runInContext(match[1], ctx);
const { computeCost, milestoneFor, validateInputs, formatCost, formatElapsed, createStopwatch, roundToCents } = ctx;

function fakeClock(start = 1_000_000) {
  let t = start;
  return { now: () => t, advance: (ms) => { t += ms; } };
}

const close = (a, b) => assert.ok(Math.abs(a - b) < 1e-9, `${a} != ${b}`);

test("logic script has no DOM access", () => {
  assert.doesNotMatch(match[1], /\b(document|window)\b/);
});

test("happy path: 6 people at $90/h for 60 s costs $9.00", () => {
  close(computeCost(6, 90, 60_000), 9);
  assert.equal(formatCost(computeCost(6, 90, 60_000)), "$9.00");
});

test("cost formula: people x rate x seconds / 3600", () => {
  close(computeCost(1, 3600, 1000), 1);
  close(computeCost(10, 100, 3_600_000), 1000);
  assert.equal(computeCost(5, 50, 0), 0);
});

test("stopwatch: pause freezes, resume continues from the frozen value", () => {
  const clock = fakeClock();
  const sw = createStopwatch(clock.now);
  sw.start();
  clock.advance(30_000);
  sw.pause();
  assert.equal(sw.elapsed(), 30_000);
  clock.advance(30_000); // paused: no change
  assert.equal(sw.elapsed(), 30_000);
  assert.equal(sw.isRunning(), false);
  sw.start();
  clock.advance(30_000);
  assert.equal(sw.elapsed(), 60_000);
  close(computeCost(6, 90, sw.elapsed()), 9);
});

test("stopwatch: reset goes to 0", () => {
  const clock = fakeClock();
  const sw = createStopwatch(clock.now);
  sw.start();
  clock.advance(12_345);
  sw.reset();
  assert.equal(sw.elapsed(), 0);
  assert.equal(sw.isRunning(), false);
  clock.advance(10_000);
  assert.equal(sw.elapsed(), 0);
});

test("display rounding: a cost that shows $100.00 triggers the 100 milestone", () => {
  assert.equal(roundToCents(99.996), 100);
  assert.equal(milestoneFor(roundToCents(99.98), roundToCents(99.996)).threshold, 100);
});

test("reset: zero elapsed gives $0.00 and 00:00:00", () => {
  assert.equal(formatCost(computeCost(6, 90, 0)), "$0.00");
  assert.equal(formatElapsed(0), "00:00:00");
});

test("formatting: dollar sign, thousands separator, 2 decimals; hh:mm:ss", () => {
  assert.equal(formatCost(1234.5678), "$1,234.57");
  assert.equal(formatElapsed(3_723_999), "01:02:03");
});

test("milestones: each threshold fires on crossing", () => {
  assert.equal(milestoneFor(99.9, 100.1).threshold, 100);
  assert.equal(milestoneFor(499, 500).threshold, 500);
  assert.equal(milestoneFor(999.99, 1000.01).threshold, 1000);
  assert.match(milestoneFor(99, 101).message, /coffee/);
  assert.match(milestoneFor(499, 501).message, /catered/);
  assert.match(milestoneFor(999, 1001).message, /laptop/);
});

test("milestones: no message when no threshold is crossed (fires once per run)", () => {
  assert.equal(milestoneFor(0, 50), null);
  assert.equal(milestoneFor(100, 150), null);
  assert.equal(milestoneFor(101, 102), null);
  assert.equal(milestoneFor(1500, 2000), null);
});

test("milestones: crossing several in one tick shows the highest", () => {
  assert.equal(milestoneFor(50, 600).threshold, 500);
  assert.equal(milestoneFor(0, 5000).threshold, 1000);
});

test("hidden tab: a 5 minute jump while running is counted, highest skipped milestone shows", () => {
  const clock = fakeClock();
  const sw = createStopwatch(clock.now);
  sw.start();
  clock.advance(36_000); // 100 people at $150/h -> $150 after 36 s
  const before = computeCost(100, 150, sw.elapsed());
  close(before, 150);
  clock.advance(5 * 60_000); // tab hidden, no ticks
  assert.equal(sw.elapsed(), 36_000 + 300_000);
  const after = computeCost(100, 150, sw.elapsed());
  close(after, 1400);
